#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <cstddef>

int main() {
    std::vector<std::string> etiquetas{"patio", "taller", "patio", "sala"};
    std::size_t posicion = etiquetas.size();
    for (std::size_t i = 0; i < etiquetas.size() && posicion == etiquetas.size(); ++i) {
        if (etiquetas[i] == "taller") { posicion = i; }
    }
    if (posicion < etiquetas.size()) { std::cout << "Primera:" << posicion; }
    else { std::cout << "No encontrado"; }
    auto ordenadas = etiquetas;
    std::sort(ordenadas.begin(), ordenadas.end());
    int distintas = 0;
    for (std::size_t i = 0; i < ordenadas.size(); ++i) {
        if (i == 0 || ordenadas[i] != ordenadas[i - 1]) { ++distintas; }
    }
    std::cout << "\nDistintas:" << distintas;
    return 0;
}

